 * This module implements a sliding window or fixed window counter logic to prevent brute-force attacks.
 */

// Assume a Redis client connection is available globally or passed in.
// For this example, we mock the Redis client interaction.
const mockRedisClient = {
    incr: async (key) => {
        // Simulate atomic increment
        console.log(`[Redis Mock] Incremented key: ${key}`);
        return 1; // Return the new value
    },
    expire: async (key, seconds) => {
        console.log(`[Redis Mock] Set expiry for key: ${key} in ${seconds}s`);
        return 1;
    },
    get: async (key) => {
        // Simulate fetching count
        return 5; // Example: already hit 5 requests
    }
};

/**
 * Configuration for the rate limiter.
 * @typedef {object} RateLimitConfig
 * @property {number} limit - Maximum requests allowed within the window.
 * @property {number} windowSeconds - Time window in seconds.
 * @property {number} violationThreshold - Number of violations before a hard block (e.g., 10).
 */

/**
 * @typedef {object} RateLimiter
 * @property {function(string): Promise<{allowed: boolean, retryAfter?: number, message?: string}>} checkRateLimit - Checks if a request is allowed.
 */

/**
 * Initializes and returns a RateLimiter instance.
 * @param {RateLimitConfig} config - Configuration settings.
 * @param {object} redisClient - An initialized Redis client interface (e.g., from app/redis_cache.py integration).
 * @returns {RateLimiter}
 */
const createRateLimiter = (config, redisClient = mockRedisClient) => {
    if (!config || typeof config.limit !== 'number' || config.limit <= 0) {
        throw new Error("Invalid RateLimitConfig provided.");
    }

    /**
     * Generates a unique key for Redis based on the identifier (e.g., IP address or User ID).
     * @param {string} identifier - IP address, user ID, etc.
     * @returns {string} The Redis key.
     */
    const getKey = (identifier) => `rate_limit:${identifier}:${Math.floor(Date.now() / (config.windowSeconds * 1000))}`;

    /**
     * Logs a rate limit violation.
     * In a real system, this would integrate with a logging service (e.g., ELK, CloudWatch).
     * @param {string} identifier - The entity that violated the limit.
     * @param {number} count - The current request count.
     */
    const logViolation = (identifier, count) => {
        console.warn(`[RATE_LIMIT_VIOLATION] Identifier: ${identifier} exceeded limit. Count: ${count}. Blocking requests.`);
        // Future: Call a dedicated logging service or alert system
    };

    /**
     * Checks if a request from a given identifier is allowed.
     * Uses Redis INCR and EXPIRE atomically.
     * @param {string} identifier - The unique identifier for the client (e.g., IP address).
     * @returns {Promise<{allowed: boolean, retryAfter?: number, message?: string}>}
     */
    const checkRateLimit = async (identifier) => {
        const key = getKey(identifier);
        const windowSeconds = config.windowSeconds;

        try {
            // 1. Atomically increment the counter
            // Note: In a real implementation, Redis pipeline/transaction (MULTI/EXEC) should be used
            // to ensure INCR and EXPIRE happen correctly if the key is new.
            let currentCount = await redisClient.incr(key);

            // 2. Set expiry only if the key was newly created (count == 1)
            if (currentCount === 1) {
                await redisClient.expire(key, windowSeconds);
            }

            // 3. Check limit
            if (currentCount > config.limit) {
                logViolation(identifier, currentCount);

                // Calculate time remaining until window resets
                const ttl = await redisClient.ttl(key); // Assuming TTL method exists
                return {
                    allowed: false,
                    retryAfter: ttl > 0 ? ttl : windowSeconds,
                    message: "Too Many Requests. Please try again later."
                };
            }

            // Allowed
            return { allowed: true };

        } catch (error) {
            console.error("Error checking rate limit for identifier ", identifier, ":", error);
            // Fail open (allow request) or fail closed (deny request). Failing open is safer for availability.
            return { allowed: true, message: "Rate limit service temporarily unavailable." };
        }
    };

    return { checkRateLimit };
};

// --- Example Usage (for testing/demonstration) ---
async function runExample() {
    const config = {
        limit: 5, // 5 requests allowed
        windowSeconds: 60, // per 60 seconds
        violationThreshold: 10
    };

    try {
        const limiter = createRateLimiter(config);
        const testIdentifier = "192.168.1.1";

        console.log("--- Testing allowed requests (1-5) ---");
        for (let i = 1; i <= 6; i++) {
            const result = await limiter.checkRateLimit(testIdentifier);
            console.log(`Request ${i}: Allowed=${result.allowed}, Message=${result.message || 'OK'}`);
            if (!result.allowed) break;
        }

    } catch (e) {
        console.error("Setup failed:", e.message);
    }
}

